    event.preventDefault();
    if (!client) return;
    void run(
      () =>
        updateMutation.mutateAsync({
          body: {
            name: name.trim(),
            redirectUris: parseRedirectUris(redirectUris),
            scopes: parseScopes(scopes),
          },
          clientId: client.clientId,
          id: applicationId,
        }),
      "OIDC client updated.",
    );
  }

